import React, { useMemo } from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); 

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type BuildingWordsProps = Record<string, any>;

const BuildingWords: React.FC<BuildingWordsProps> = ({
  backgroundColor = "#111111",
  transparentBackground = false,
  durationInSeconds = 8,
  brickColor = "#e67e22",
  accentColor = "#d35400",
  titleText = "Building Words",
  textColor = "#ecf0f1",
  rows = 2,
  cols = 2,
  gap = 12,
}) => {
  useFontLoader(["Montserrat"]);

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Color logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Grid calculations
  const maxGridWidth = width * 0.15;
  const brickWidth = (maxGridWidth - (cols - 1) * gap) / cols;
  
  // UPDATED: Make height half of width for "long rectangular brick" shape
  const brickHeight = brickWidth * 0.5; 
  
  const gridWidth = cols * brickWidth + (cols - 1) * gap;
  const gridHeight = rows * brickHeight + (rows - 1) * gap;

  const startX = (width - gridWidth) / 2;
  const startY = (height - gridHeight) / 2 - (height * 0.05); // Centered vertically

  // Circle Dimensions
  const circleDiameter = Math.sqrt(gridWidth ** 2 + gridHeight ** 2) * 1.6;
  const circleRadius = circleDiameter / 2;
  const circleX = startX + gridWidth / 2 - circleRadius;
  const circleY = startY + gridHeight / 2 - circleRadius;

  // Generate brick data
  const bricks = useMemo(() => {
    const b = [];
    const letters = "ABCDEFGHIJKLMNOPQRSTUVWXYZ";
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const letterIndex = (r * cols + c) % letters.length;
        b.push({ 
            r, 
            c, 
            id: `r${r}-c${c}`,
            char: letters[letterIndex] 
        });
      }
    }
    return b;
  }, [rows, cols]);

  // Text Animation
  const textDelay = rows * 10; 
  const textOpacity = spring({
    frame: frame - textDelay,
    fps,
    config: { mass: 2, damping: 50 }
  });
  
  const textTranslate = interpolate(textOpacity, [0, 1], [50, 0]);

  // Circle Animation
  const circleScale = spring({
    frame,
    fps,
    config: { mass: 3, damping: 200, stiffness: 100 }
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Montserrat" }}>
      
      {/* Circle Outline - Updated to Glowing Yellow */}
      <div
        style={{
          position: "absolute",
          left: circleX,
          top: circleY,
          width: circleDiameter,
          height: circleDiameter,
          borderRadius: "50%",
          // Thicker border for the ring, set to yellow
          border: `${Math.max(10, width * 0.012)}px solid #FFD700`,
          // Added glow effect
          boxShadow: "0 0 30px #FFD700, inset 0 0 30px #FFD700",
          opacity: 0.8,
          transform: `scale(${circleScale})`,
        }}
      />

      {/* Bricks Container with 3D Perspective */}
      <div
        style={{
          position: "absolute",
          left: startX,
          top: startY,
          width: gridWidth,
          height: gridHeight,
          perspective: "1200px", // Adds depth to the scene
          transformStyle: "preserve-3d",
        }}
      >
        <div style={{
           position: "relative",
           width: "100%",
           height: "100%",
           transform: "rotateX(25deg)", // Tilts the grid for 3D effect
           transformStyle: "preserve-3d",
        }}>
          {bricks.map((brick) => {
              // Logic: Build from bottom (last row) to top (first row)
              const invertedRow = (rows - 1) - brick.r;
              
              // Stagger
              const delay = (invertedRow * 15) + (brick.c * 5);

              const dropProgress = spring({
                  frame: frame - delay,
                  fps,
                  config: {
                      damping: 12,
                      stiffness: 150,
                      mass: 0.8,
                  }
              });

              // Randomize color slightly for texture
              const isAccent = (brick.r + brick.c) % 2 === 0;
              const finalColor = isAccent ? accentColor : brickColor;

              // Animation values
              // Using Z-axis translate for drop to enhance 3D feel
              const zOffset = interpolate(dropProgress, [0, 1], [800, 0]);
              const opacity = interpolate(dropProgress, [0, 0.5], [0, 1]);
              const scale = interpolate(dropProgress, [0, 0.8, 1], [0, 1.1, 1]);

              return (
                  <div
                      key={brick.id}
                      style={{
                          position: "absolute",
                          left: brick.c * (brickWidth + gap),
                          top: brick.r * (brickHeight + gap),
                          width: brickWidth,
                          height: brickHeight,
                          // UPDATED: Transparent background
                          backgroundColor: "transparent",
                          borderRadius: brickHeight * 0.1,
                          opacity,
                          transform: `translateZ(${zOffset}px) scale(${scale})`,
                          // UPDATED: Outline style only
                          border: `${Math.max(2, brickWidth * 0.05)}px solid ${finalColor}`,
                          // UPDATED: Removed 3D depth/shadows for clean outline look
                          boxShadow: 'none',
                          // Center content (the letter)
                          display: "flex",
                          justifyContent: "center",
                          alignItems: "center",
                          boxSizing: 'border-box' 
                      }}
                  >
                   {/* Text Removed per request */}
                  </div>
              );
          })}
        </div>
      </div>

      {/* Text Container */}
      <div
        style={{
            position: "absolute",
            bottom: height * 0.15,
            width: "100%",
            textAlign: "center",
            opacity: textOpacity,
            transform: `translateY(${textTranslate}px)`,
        }}
      >
        <h1
            style={{
                margin: 0,
                color: textColor,
                fontSize: width * 0.04,
                fontWeight: 900,
                textTransform: "uppercase",
                letterSpacing: "-0.02em",
                textShadow: "0 10px 30px rgba(0,0,0,0.5)",
            }}
        >
            {titleText}
        </h1>
        <div 
            style={{
                width: width * 0.05,
                height: 4,
                backgroundColor: accentColor,
                margin: "15px auto",
                borderRadius: 2,
            }} 
        />
      </div>

    </AbsoluteFill>
  );
};

export default BuildingWords;